import static java.lang.StringTemplate.STR;
import static java.util.FormatProcessor.FMT;

public class StringTemplateDemo {
    public static void main(String[] args) {
        String firstName = "Ada";
        String lastName = "Lovelace";
        int age = 36;

        // Standard STR Processor
        String greeting = STR."My name is \{firstName} \{lastName} and I am \{age} years old.";
        System.out.println(greeting);

        // FMT Processor with formatting specifiers
        double pi = Math.PI;
        String formattedPi = FMT."Value of Pi to 4 decimal places: \%(.4f\{pi}%%";
        System.out.println(formattedPi);
    }
}
